  "description": "Read accessible Atlassian sites, search and read Confluence pages, and search and read Jira issues.",
  "type": "module",
  "exports": {
    ".": "./index.ts"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.1"
  },
  "executor": {
