import {
  array,
  bearer,
  decodeJson,
  defineProvider,
  object,
  oauth2,
  string,
  type QueryContext,
} from "apps";
import { apiOrigin, scopes } from "./configuration.js";
export { apiOrigin };

export const accessibleResourcesUrl = `${apiOrigin}/oauth/token/accessible-resources`;
const atlassian = defineProvider({
  name: "Atlassian",
  hosts: ["api.atlassian.com"],
  auth: {
    oauth: oauth2({
      authorizationUrl: "https://auth.atlassian.com/authorize",
      tokenUrl: "https://auth.atlassian.com/oauth/token",
      tokenEndpointAuthMethod: "client_secret_post",
      tokenRequestFormat: "json",
      authorizationParams: { audience: "api.atlassian.com", prompt: "consent" },
      scopes,
      request: ({ access_token }) => bearer(access_token),
    }),
  },
  async health({ account, fetch, signal }) {
    const response = await fetch(accessibleResourcesUrl, {
      signal,
      headers: { ...account.headers(), accept: "application/json" },
    });
    const sites = await decodeJson(response, array(object({ id: string(), name: string() })));
    if (sites.length === 0) throw new Error("No Atlassian sites are accessible to this account.");
  },
});

export const requirements = { user: { accounts: { atlassian } } };

export const apiFetch = (
  context: QueryContext<typeof requirements>,
  url: string,
  options: { readonly method?: "GET" | "POST"; readonly body?: unknown } = {},
) => {
  const body = options.body === undefined ? undefined : JSON.stringify(options.body);
  return context.fetch(url, {
    ...(options.method === undefined ? {} : { method: options.method }),
    ...(body === undefined ? {} : { body }),
    signal: context.signal,
    headers: {
      ...context.user.accounts.atlassian.headers(),
      accept: "application/json",
      ...(body === undefined ? {} : { "content-type": "application/json" }),
    },
  });
};

import { array, boolean, decodeJson, json, number, object, query, string } from "apps";
import type { QueryContext } from "apps";
import { never } from "apps/operations/approval";
import { apiFetch, apiOrigin, accessibleResourcesUrl, type requirements } from "./provider.js";

const boundedNumber = (value: number | undefined, fallback: number, maximum: number) =>
  Math.max(1, Math.min(maximum, Math.trunc(value ?? fallback)));

const Sites = array(
  object({
    id: string(),
    name: string(),
    url: string(),
    scopes: array(string()).optional(),
  }),
);

const listSites = query(
  {
    description: "List Atlassian Cloud sites accessible to the connected account.",
    approval: never(),
    input: object({}),
  },
  async (context: QueryContext<typeof requirements>) => {
    const response = await apiFetch(context, accessibleResourcesUrl);
    return decodeJson(response, Sites);
  },
);

const ConfluenceSearch = object({
  results: array(
    object({
      id: string(),
      title: string(),
      type: string().optional(),
      status: string().optional(),
      excerpt: string().optional(),
      space: object({ key: string().optional(), name: string().optional() }).optional(),
      _links: object({ webui: string().optional() }).optional(),
    }),
  ),
  size: number().optional(),
});

const searchConfluence = query(
  {
    description: "Search Confluence pages with a CQL query on one accessible site.",
    approval: never(),
    input: object({
      cloudId: string({ minLength: 1 }),
      cql: string({ minLength: 1 }),
      limit: number().optional(),
    }),
  },
  async (context: QueryContext<typeof requirements>, { cloudId, cql, limit }) => {
    const params = new URLSearchParams({
      cql,
      limit: String(boundedNumber(limit, 25, 100)),
      expand: "space",
    });
    const base = `${apiOrigin}/ex/confluence/${encodeURIComponent(cloudId)}/wiki/rest/api`;
    const response = await apiFetch(context, `${base}/content/search?${params}`);
    return decodeJson(response, ConfluenceSearch);
  },
);

const ConfluencePage = object({
  id: string(),
  title: string(),
  type: string().optional(),
  status: string().optional(),
  space: object({ key: string().optional(), name: string().optional() }).optional(),
  body: object({
    storage: object({ value: string(), representation: string().optional() }).optional(),
  }).optional(),
  _links: object({ webui: string().optional() }).optional(),
});

const readConfluencePage = query(
  {
    description: "Read a Confluence page and its storage-format body.",
    approval: never(),
    input: object({ cloudId: string({ minLength: 1 }), pageId: string({ minLength: 1 }) }),
  },
  async (context: QueryContext<typeof requirements>, { cloudId, pageId }) => {
    const base = `${apiOrigin}/ex/confluence/${encodeURIComponent(cloudId)}/wiki/rest/api`;
    const params = new URLSearchParams({ expand: "body.storage,space,version" });
    const response = await apiFetch(
      context,
      `${base}/content/${encodeURIComponent(pageId)}?${params}`,
    );
    return decodeJson(response, ConfluencePage);
  },
);

const JiraIssue = object({
  id: string(),
  key: string(),
  self: string().optional(),
  fields: object({
    summary: string(),
    description: json().optional(),
    status: object({ name: string() }).optional(),
    issuetype: object({ name: string() }).optional(),
    project: object({ key: string(), name: string().optional() }).optional(),
    updated: string().optional(),
  }),
});

const getJiraIssue = query(
  {
    description: "Read a Jira issue by key from one accessible site.",
    approval: never(),
    input: object({ cloudId: string({ minLength: 1 }), issueKey: string({ minLength: 1 }) }),
  },
  async (context: QueryContext<typeof requirements>, { cloudId, issueKey }) => {
    const base = `${apiOrigin}/ex/jira/${encodeURIComponent(cloudId)}/rest/api/3`;
    const params = new URLSearchParams({
      fields: "summary,description,status,issuetype,project,updated",
    });
    const response = await apiFetch(
      context,
      `${base}/issue/${encodeURIComponent(issueKey)}?${params}`,
    );
    return decodeJson(response, JiraIssue);
  },
);

const JiraSearch = object({
  issues: array(JiraIssue),
  total: number().optional(),
  isLast: boolean().optional(),
  nextPageToken: string().optional(),
});

const searchJiraIssues = query(
  {
    description: "Search Jira issues with JQL on one accessible site.",
    approval: never(),
    input: object({
      cloudId: string({ minLength: 1 }),
      jql: string({ minLength: 1 }),
      maxResults: number().optional(),
    }),
  },
  async (context: QueryContext<typeof requirements>, { cloudId, jql, maxResults }) => {
    const base = `${apiOrigin}/ex/jira/${encodeURIComponent(cloudId)}/rest/api/3`;
    const response = await apiFetch(context, `${base}/search/jql`, {
      method: "POST",
      body: {
        jql,
        maxResults: boundedNumber(maxResults, 25, 100),
        fields: ["summary", "status", "issuetype", "project", "updated"],
      },
    });
    return decodeJson(response, JiraSearch);
  },
);

export { listSites, searchConfluence, readConfluencePage, getJiraIssue, searchJiraIssues };

import type { OpenapiToolNamesOptions } from "apps/openapi";
import coverage from "./api-coverage.json" with { type: "json" };
import { apiOrigin } from "./configuration.js";

export type ApiName = keyof typeof coverage;
const pointer = (value: string) => value.replaceAll("~", "~0").replaceAll("/", "~1");

export function optionsFor(name: ApiName) {
  const api = coverage[name];
  return {
    title: api.title,
    source: { url: api.url },
    allowedOrigin: apiOrigin,
    baseUrl: apiOrigin,
    pathPrefix: api.pathPrefix,
    securitySchemes: { [api.scheme]: { type: "http", scheme: "bearer" } },
    methods: { oauth: [{ scheme: api.scheme, field: "access_token", part: "value", prefix: "" }] },
    oauth: [],
    kinds: Object.fromEntries(api.queries.map((id) => [id, "query" as const])),
    patches: [
      ...api.excluded.map((operation) => ({
        op: "remove" as const,
        path: `/paths/${pointer(operation.path)}/${operation.method}`,
      })),
      // The documented flat and nested page bodies must match only their own branch.
      ...(name === "confluenceV2"
        ? ["PageBodyWrite", "PageNestedBodyWrite"].map((schema) => ({
            op: "add" as const,
            path: `/components/schemas/${schema}/additionalProperties`,
            value: false,
          }))
        : []),
    ],
  } satisfies OpenapiToolNamesOptions & { title: string };
}

import coverage from "./api-coverage.json" with { type: "json" };
import { apiOrigin } from "./configuration.js";
import type { ApiName } from "./openapi.js";

type AppFetch = (input: string | URL | Request, init?: RequestInit) => Promise<Response>;
const templatePattern = (value: string) =>
  new RegExp(
    "^" +
      value
        .split(/(\{[^}]+\})/)
        .map((part) =>
          part.startsWith("{") ? "[^/]+" : part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
        )
        .join("") +
      "$",
  );

/** Add only the fixed headers the vendor requires for these exact API operations. */
export function fetchFor(name: ApiName, fetch: AppFetch): AppFetch {
  const api = coverage[name];
  const rules = api.requiredHeaders.map((rule) => ({
    ...rule,
    pattern: templatePattern(api.pathPrefix + rule.path),
  }));
  return (input, init = {}) => {
    const request = input instanceof Request ? input : undefined;
    const url = new URL(request?.url ?? input.toString());
    const method = (init.method ?? request?.method ?? "GET").toUpperCase();
    const rule =
      url.origin === apiOrigin
        ? rules.find((rule) => rule.method === method && rule.pattern.test(url.pathname))
        : undefined;
    if (rule === undefined) return fetch(input, init);
    const headers = new Headers(init.headers ?? request?.headers);
    for (const [name, value] of Object.entries(rule.headers)) headers.set(name, value);
    return fetch(input, { ...init, headers, redirect: "manual" });
  };
}

import type { AppCache, CacheGetOptions, CacheLoadContext, JsonValue } from "apps";
import coverage from "./api-coverage.json" with { type: "json" };
import type { ApiName } from "./openapi.js";

const maximumDocumentBytes = 40_000_000;

async function verifiedResponse(response: Response, expected: string): Promise<Response> {
  if (!response.ok || response.body === null) return response;
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let length = 0;
  try {
    for (;;) {
      const chunk = await reader.read();
      if (chunk.done) break;
      length += chunk.value.byteLength;
      if (length > maximumDocumentBytes)
        throw new Error("Atlassian OpenAPI document exceeds 40 MB.");
      chunks.push(chunk.value);
    }
  } finally {
    await reader.cancel();
  }
  const bytes = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  const actual = Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");
  if (actual !== expected)
    throw new Error(
      "Atlassian OpenAPI document changed. Review its scopes and exclusions before updating the recorded hash.",
    );
  return new Response(bytes, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}

/** Guard the SDK's loader-owned fetch and bind every compiled cache entry to the reviewed hash. */
export function specificationCache(name: ApiName, cache: AppCache): AppCache {
  const api = coverage[name];
  const key = (value: JsonValue): JsonValue => [
    "atlassian-reviewed-spec",
    api.url,
    api.sha256,
    value,
  ];
  const options = <A>(original: CacheGetOptions<A>): CacheGetOptions<A> => ({
    ...original,
    key: key(original.key),
    load: (context: CacheLoadContext) =>
      original.load({
        ...context,
        cache: specificationCache(name, context.cache),
        fetch: async (input, init) => {
          const request = input instanceof Request ? input : undefined;
          const url = new URL(request?.url ?? input.toString());
          const method = (init?.method ?? request?.method ?? "GET").toUpperCase();
          const response = await context.fetch(input, init);
          return url.href === api.url && method === "GET"
            ? verifiedResponse(response, api.sha256)
            : response;
        },
      }),
  });
  return {
    get: (original) => cache.get(options(original)),
    revalidate: (original) => cache.revalidate(options(original)),
    read: (value, schema) => cache.read(key(value), schema),
    readMany: (values, schema) => cache.readMany(values.map(key), schema),
    write: (entries, retention) =>
      cache.write(
        entries.map((entry) => ({ ...entry, key: key(entry.key) })),
        retention,
      ),
    invalidate: (value) => cache.invalidate(key(value)),
    forAccount: (account) => specificationCache(name, cache.forAccount(account)),
  };
}

